module TopModule (
    input  logic clk,
    input  logic areset,
    input  logic x,
    output logic z
);

    typedef enum logic [1:0] {
        S0     = 2'b00,
        S_OUT1 = 2'b01,
        S_OUT0 = 2'b10
    } state_t;

    state_t current_state, next_state;

    // State register with positive-edge asynchronous reset
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= S0;
        end else begin
            current_state <= next_state;
        end
    end

    // Next state logic
    always_comb begin
        case (current_state)
            S0: begin
                if (x) next_state = S_OUT1;
                else   next_state = S0;
            end
            S_OUT1: begin
                if (x) next_state = S_OUT0;
                else   next_state = S_OUT1;
            end
            S_OUT0: begin
                if (x) next_state = S_OUT0;
                else   next_state = S_OUT1;
            end
            default: next_state = S0;
        endcase
    end

    // Output logic (Moore: depends only on current state)
    always_comb begin
        case (current_state)
            S0:     z = 1'b0;
            S_OUT1: z = 1'b1;
            S_OUT0: z = 1'b0;
            default: z = 1'b0;
        endcase
    end

endmodule

